Node *merge(Node *a, Node *b) {
  Node *rNode = NULL;
  if (a == NULL) {
    return b;
  } else if (b == NULL) {
    return a;
  }

  if (a->data <= b->data) {
    rNode = a;
    rNode->next = merge(a->next, b);
  } else {
    rNode = b;
    rNode->next = merge(a, b->next);
  }
  return rNode;
}

Node *mergeSort(Node *head) {
  if (head == NULL) {
    return NULL;
  }
  if (head->next == NULL) {
    return head;
  }

  Node *a;
  Node *b;
  split(head, a, b);
  a = mergeSort(a);
  b = mergeSort(b);
  return merge(a, b);
}

